  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build lookup for distances between nodes (undirected)
    dist_dict = {}
    for a, b, d in distances:
        key = (a, b) if a < b else (b, a)
        dist_dict[key] = d

    # Generate all unordered pairs from nodes
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i + 1, n):
            u = nodes[i]
            v = nodes[j]
            key = (u, v) if u < v else (v, u)
            if key not in dist_dict:
                raise ValueError(f"Missing distance between {u} and {v}")
            d = dist_dict[key]
            w = max(core_distance[u], core_distance[v], d)
            edges.append((w, u, v))

    # Sort edges: weight, then first node, then second node (both strings)
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Disconnected graph: cannot form a spanning tree")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
